import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(aLine[i]);
        }

        int half = n / 2;
        List<Long> part1 = new ArrayList<>();
        List<Long> part2 = new ArrayList<>();

        // Compute sums for part1
        computeSumsPart1(0, 0, a, m, half, part1);
        // Compute sums for part2
        computeSumsPart2(half, 0, a, m, n, part2);

        // Remove duplicates and sort part1
        TreeSet<Long> setPart1 = new TreeSet<>(part1);
        List<Long> part1UniqueSorted = new ArrayList<>(setPart1);

        long bestTotal = 0;
        for (Long val : part2) {
            int index = Collections.binarySearch(part1UniqueSorted, m - val);
            if (index < 0) {
                index = -index - 1;
            }
            if (index > 0) {
                long totalCandidate = part1UniqueSorted.get(index - 1) + val;
                if (totalCandidate > bestTotal) {
                    bestTotal = totalCandidate;
                }
            }
        }
        System.out.println(bestTotal);
    }

    private static void computeSumsPart1(int i, long currentSum, long[] a, int m, int half, List<Long> part1) {
        if (i == half) {
            part1.add(currentSum);
        } else {
            computeSumsPart1(i + 1, (currentSum + a[i]) % m, a, m, half, part1);
            computeSumsPart1(i + 1, currentSum, a, m, half, part1);
        }
    }

    private static void computeSumsPart2(int i, long currentSum, long[] a, int m, int n, List<Long> part2) {
        if (i == n) {
            part2.add(currentSum);
        } else {
            computeSumsPart2(i + 1, (currentSum + a[i]) % m, a, m, n, part2);
            computeSumsPart2(i + 1, currentSum, a, m, n, part2);
        }
    }
}
